ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(
        Coalesce(
            If(!IsBlank(varImage) && varImage <> SampleImage, varImage, Blank()),
            If(
                !IsBlank(varImageUrl),
                Coalesce(LookUp(colHomeQueue, id = varHomeSelectedId).image, varImageUrl),
                Blank()
            )
        )
    ),
    Set(varError, "先に写真を撮影またはアップロードしてください"),

    Set(varBusy, true);
    Set(varError, "");
    Set(varFromUnknownList, false);
    Set(varHomeQueueId, Coalesce(varHomeSelectedId, ""));
    Clear(varCandidates);
    Clear(colSelected);
    Set(varSearchText, "");
    Set(varSelectedRecipientId, "");
    IfError(
        Set(
            varResult,
            'EDS-ProcessLabel'.Run(
                {
                    contentBytes: Coalesce(
                        If(!IsBlank(varImage) && varImage <> SampleImage, varImage, Blank()),
                        LookUp(colHomeQueue, id = varHomeSelectedId).image,
                        varImageUrl
                    ),
                    name: With(
                        {
                            spPath: LookUp(colHomeQueue, id = varHomeSelectedId).path
                        },
                        If(
                            !IsBlank(spPath),
                            "SPPATH|" & spPath,
                            Coalesce(varImageName, "label.jpg")
                        )
                    )
                }
            )
        );

        If(
            !Coalesce(varResult.is_package_label, false),
            Set(varError, "無効な画像です。もう一度お試しください");
            Set(varBusy, false),

            Set(varTier, Lower(Trim(Text(Coalesce(varResult.tier, "")))));
            Set(varMatchScore, Coalesce(Value(Text(varResult.match_score)), 0));
            Set(varOcrName, Text(Coalesce(varResult.receiver_name, "")));
            Set(varOcrDept, Text(Coalesce(varResult.department, "")));
            Set(varOcrConf, Coalesce(Value(Text(varResult.ocr_confidence)), 0));
            Set(varOcrSenderName, Text(Coalesce(varResult.sender_name, "")));
            Set(varOcrSenderInfo, Text(Coalesce(varResult.sender_info, "")));
            Set(varOcrSenderDepartment, Text(Coalesce(varResult.sender_department, "")));
            Set(varOcrDeliverySlip, Text(Coalesce(varResult.slip_no, "")));

            ClearCollect(
                varCandidates,
                ForAll(
                    Table(ParseJSON(Coalesce(varResult.candidates_json, "[]"))),
                    {
                        employee_id: Text(ThisRecord.Value.employee_id),
                        name: Text(ThisRecord.Value.name),
                        department: Text(ThisRecord.Value.department),
                        email: Text(ThisRecord.Value.email),
                        teams_id: Text(ThisRecord.Value.teams_id),
                        score: Value(ThisRecord.Value.score)
                    }
                )
            );

            Clear(colSelected);
            If(
                CountRows(varCandidates) = 1,
                With(
                    { onlyCand: First(varCandidates) },
                    Set(varSelectedRecipientId, onlyCand.employee_id);
                    Collect(
                        colSelected,
                        {
                            employee_id: onlyCand.employee_id,
                            name: onlyCand.name,
                            department: onlyCand.department,
                            email: onlyCand.email,
                            teams_id: onlyCand.teams_id,
                            score: Coalesce(onlyCand.score, 0),
                            is_cc: false
                        }
                    )
                )
            );
            Set(varMatchStep, 1);
            Set(varError, "");
            Set(varBusy, false);
            Navigate(srcMatchResult, ScreenTransition.None)
        ),

        Set(
            varError,
            "認識に失敗しました: " & Coalesce(FirstError.Message, "もう一度お試しください。")
        );
        Set(varBusy, false)
    )
)

