    Set(varMatchScore, 0);
    Set(varOcrName, "");
    Set(varOcrDept, "");
    Set(varOcrConf, 0);
    Set(varOcrSenderName, "");
    Set(varOcrSenderInfo, "");
    Set(varOcrSenderDepartment, "");
    Set(varOcrDeliverySlip, "");
    Set(varMatchStep, 1);
    If(
        (IsBlank(varImage) || varImage = SampleImage)
